arguments.content:
var qs = require('./lib');

console.log('=== Edge Case Tests ===\n');

// Test 1: Original issue - overflow array + array
var result1 = qs.parse('a=1,2,3,4,5,6&a=7,8', { comma: true, arrayLimit: 5 });
console.log('Test 1 (Original issue):', JSON.stringify(result1));
console.assert(result1.a['6'] === '7', 'Test 1a failed');
console.assert(result1.a['7'] === '8', 'Test 1b failed');
console.assert(typeof result1.a['6'] !== 'object', 'Test 1c: should not be nested');
console.log('  PASSED\n');

// Test 2: Without overflow case should still work
var result2 = qs.parse('a=1,2,3,4,5&a=6,7,8', { comma: true, arrayLimit: 5 });
console.log('Test 2 (No overflow case):', JSON.stringify(result2));
console.assert(result2.a['5'] === '6', 'Test 2a failed');
console.assert(result2.a['7'] === '8', 'Test 2b failed');
console.log('  PASSED\n');

// Test 3: Multiple overflow concatenations
var result3 = qs.parse('a=1,2,3,4,5,6&a=7,8,9&a=10,11', { comma: true, arrayLimit: 5 });
console.log('Test 3 (Multiple overflow concat):', JSON.stringify(result3));
console.assert(result3.a['6'] === '7', 'Test 3a failed');
console.assert(result3.a['8'] === '9', 'Test 3b failed');
console.assert(result3.a['9'] === '10', 'Test 3c failed');
console.assert(result3.a['10'] === '11', 'Test 3d failed');
console.log('  PASSED\n');

// Test 4: Single value after overflow
var result4 = qs.parse('a=1,2,3,4,5,6&a=single', { comma: true, arrayLimit: 5 });
console.log('Test 4 (Single value after overflow):', JSON.stringify(result4));
console.assert(result4.a['6'] === 'single', 'Test 4 failed');
console.assert(typeof result4.a['6'] !== 'object', 'Test 4b: should not be nested');
console.log('  PASSED\n');

// Test 5: Empty string after overflow
var result5 = qs.parse('a=1,2,3,4,5,6&a=', { comma: true, arrayLimit: 5 });
console.log('Test 5 (Empty string after overflow):', JSON.stringify(result5));
console.assert(result5.a['6'] === '', 'Test 5 failed');
console.log('  PASSED\n');

// Test 6: Overflow object combined with overflow object
var result6 = qs.parse('a=1,2,3,4,5,6,7&a=8,9,10', { comma: true, arrayLimit: 3 });
console.log('Test 6 (Overflow + overflow):', JSON.stringify(result6));
console.assert(result6.a['6'] === '8', 'Test 6a failed');
console.assert(result6.a['7'] === '9', 'Test 6a failed');
console.assert(result6.a['8'] === '10', 'Test 6b failed');
console.log('  PASSED\n');

// Test 7: Non-comma mode should not be affected
var result7 = qs.parse('a=1,2,3,4,5,6&a=7,8', { comma: false, arrayLimit: 5 });
console.log('Test 7 (Non-comma mode):', JSON.stringify(result7));
// Without comma: true, "1,2,3,4,5,6" is treated as a single value
console.log('  PASSED (no comma mode)\n');

// Test 8: Array limit exactly met, then more values
var result8 = qs.parse('a=1,2,3,4,5&a=6', { comma: true, arrayLimit: 5 });
console.log('Test 8 (Array limit exactly met):', JSON.stringify(result8));
