var qs = require('./lib');

console.log('=== Edge Case Tests ===\n');

// Test 1: Original issue - overflow array + array
var result1 = qs.parse('a=1,2,3,4,5,6&a=7,8', { comma: true, arrayLimit: 5 });
console.log('Test 1 (Original issue):', JSON.stringify(result1));
console.assert(result1.a['6'] === '7', 'Test 1a failed');
console.assert(result1.a['7'] === '8', 'Test 1b failed');
console.assert(typeof result1.a['6'] !== 'object', 'Test 1c: should not be nested');
console.log('  PASSED\n');

// Test 2: Without overflow case should still work
var result2 = qs.parse('a=1,2,3,4,5&a=6,7,8', { comma: true, arrayLimit: 5 });
console.log('Test 2 (No overflow case):', JSON.stringify(result2));
console.assert(result2.a['5'] === '6', 'Test 2a failed');
console.assert(result2.a['7'] === '8', 'Test 2b failed');
console.log('  PASSED\n');

// Test 3: Multiple overflow concatenations
